from pathlib import Path
from datetime import datetime
import base64
import shutil
import py_compile

ROOT = Path.cwd()

REQUIRED = [
    ROOT / "src/scoring/research_scoring.py",
    ROOT / "src/enrichment/profiles.py",
]

missing = [str(p) for p in REQUIRED if not p.exists()]
if missing:
    print("エラー：clinic-list-filter-complete フォルダで実行してください。")
    print("見つからないファイル:")
    for p in missing:
        print(" -", p)
    raise SystemExit(1)

stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
backup = ROOT / ("code_backup_research_v25_" + stamp)
backup.mkdir(parents=True, exist_ok=False)

targets = [
    ROOT / "src/scoring/research_scoring.py",
    ROOT / "src/enrichment/profiles.py",
    ROOT / "export_research_v25_results.py",
]

for p in targets:
    if p.exists():
        rel = p.relative_to(ROOT)
        dst = backup / rel
        dst.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(p, dst)

PAYLOADS = {
    "src/scoring/research_scoring.py": '',
    "src/enrichment/profiles.py": '',
    "export_research_v25_results.py": '',
}

try:
    for rel, encoded in PAYLOADS.items():
        path = ROOT / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(base64.b64decode(encoded))

    py_compile.compile(str(ROOT / "src/scoring/research_scoring.py"), doraise=True)
    py_compile.compile(str(ROOT / "src/enrichment/profiles.py"), doraise=True)
    py_compile.compile(str(ROOT / "export_research_v25_results.py"), doraise=True)

    (ROOT / "VERSION_RESEARCH").write_text("2.5-research\n", encoding="utf-8")

except Exception as e:
    print("適用中にエラーが発生したため、バックアップから戻します。")
    for p in targets:
        rel = p.relative_to(ROOT)
        src = backup / rel
        if src.exists():
            p.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(src, p)
    print("エラー:", repr(e))
    raise SystemExit(1)

print("修正しました。")
print("【v25の変更】")
print("1. 年齢推定")
print("   ・複数医師ページでも、現在の管理者/院長本人の経歴ブロックを優先します。")
print("   ・卒業年/医籍年は『卒業』『医師免許』『医籍』『国家試験合格』の直近年を採用します。")
print("   ・後続の勤務年、医学博士取得年、他医師の卒業年を混ぜにくくしました。")
print("2. 広告・集客施策")
print("   ・『オンライン診療終了/休止/中止』はオンライン診療シグナルに加点しません。")
print("   ・WordPress.org / Powered by WordPress はHP制作会社シグナルにしません。")
print("   ・Doctors File等の媒体リンクをHP制作会社として二重加点しません。")
print("3. 内視鏡カテゴリ")
print("   ・消化器内視鏡を対象にし、美容外科等の『内視鏡下手術』だけでは内視鏡カテゴリにしません。")
print("   ・胃カメラ/大腸内視鏡/消化管内視鏡/ポリープ等は従来どおり対象です。")
print("・v24の治療カテゴリ優先順位、昼枠、HPランク、Maps連携は維持します。")
print("・SQLite、UUID、Google Maps取込結果、Comdesk元データは変更していません。")
print("・比較用出力: export_research_v25_results.py")
print("バックアップ:", backup.name)
